// === Tab: mySketch ===
//deeply indebted to Daniel Shiffman's Coding train videos for help with this

particles = [];
r = 0

function setup() {
  createCanvas(windowWidth, windowHeight);
  colorMode(HSB, 100);
  angleMode(DEGREES);
  rectMode(CENTER);
  drawingContext.shadowOffsetX = 0;
  drawingContext.shadowOffsetY = 0;
  drawingContext.shadowBlur = 10;
  drawingContext.shadowColor = 'white';
}

function draw() {
  background(0);

  push()
  translate((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
  noStroke();
  fill(random(0, 15), 10, 100, 50);

  ellipse(0, 0, 10, 10);

  pop();



  for (let i=0; i<15; i++){
    let p = new Particle();
    particles.push(p);
}
  for (let i = particles.length -1; i>=0; i--){
    particles[i].show();
    particles[i].update();

    if (particles[i].finished()){
      particles.splice(i, 1);
    }
  }
}

class Particle {

  constructor() {
    this.x= (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)));
    this.y= (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)));
    this.vx = random(-2, 2);
    this.vy = random(-2, 3);
    this.alpha = 100;

  }

  finished() {
    return this.alpha < 0;
  }

  update() {
    this.x += this.vx;
    this.y += this.vy;
    this.alpha-=2

  }

  show (){

    strokeWeight(random(1, 4));
    stroke(random(1, 15),50, 100, this.alpha);
    point(this.x, this.y);
  }
}

